// Sheet header -> CONTRACT.md section 5 flat keys.
// 'Read Processing Log' has Always Output Data on, so an empty sheet arrives as
// a single {} item; filter those out and return [] for an empty log.
const COLS = {
  document_id: 'Document ID',
  received_at: 'Received At',
  file_name: 'File Name',
  file_link: 'File Link',
  document_type: 'Document Type',
  sender_or_company: 'Sender / Company',
  summary: 'Summary',
  requested_action: 'Requested Action',
  deadline: 'Deadline',
  urgency: 'Urgency',
  department: 'Department',
  status: 'Status',
};
const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => String(r['Document ID'] ?? '').trim() !== '');
const documents = rows.map((json) => {
  const out = {};
  for (const [key, col] of Object.entries(COLS)) {
    const v = json[col];
    out[key] = (v === undefined || v === null || v === '')
      ? (key === 'requested_action' ? 'No action found' : 'Not found')
      : v;
  }
  return out;
});
return [{ json: { documents } }];
